
      /* ===== Yahan apni details badlo ===== */
      var CONFIG = {
        herName: "Jaan", // uska pyaar wala naam
        myName: "Tumhara pyaar", // khat ke neeche tumhara naam
        startDate: "2017-07-13T11:00:00", // jis din se saath ho (khali "" chhodo to counter chhup jayega)
        memories: [
          // src me photo ka data/URL daalo
          {
            src: "data:image/jpeg;base64,",
            caption: "Hum dono, ek saath",
            date: "",
          },
          {
            src: "data:image/jpeg;base64,",
            caption: "Tumhara sar mere kandhe pe",
            date: "",
          },
          {
            src: "data:image/jpeg;base64,",
            caption: "Wo pyaari si muskaan",
            date: "",
          },
          {
            src: "data:image/jpeg;base64,",
            caption: "Ped ke neeche, chhupke se",
            date: "",
          },
          {
            src: "data:image/jpeg;base64,",
            caption: "Park wali shaam",
            date: "1 May 2023",
          },
          {
            src: "data:image/jpeg;base64,",
            caption: "Station pe, tumhare saath",
            date: "",
          },
        ],
      };
      /* ==================================== */

      (function () {
        var reduce =
          window.matchMedia &&
          window.matchMedia("(prefers-reduced-motion: reduce)").matches;
        var $ = function (id) {
          return document.getElementById(id);
        };

        document.querySelectorAll(".her").forEach(function (n) {
          n.textContent = CONFIG.herName;
        });
        document.querySelectorAll(".me").forEach(function (n) {
          n.textContent = CONFIG.myName;
        });

        /* Envelope */
        var intro = $("intro"),
          site = $("site"),
          opened = false;
        function openIt() {
          if (opened) return;
          opened = true;
          intro.classList.add("open");
          setTimeout(
            function () {
              site.classList.add("show");
              var hero = document.querySelector(".hero-in");
              if (hero) hero.classList.add("hero-in");
              window.scrollTo(0, 0);
              intro.classList.add("gone");
              setTimeout(function () {
                intro.style.display = "none";
              }, 1000);
            },
            reduce ? 100 : 1900,
          );
        }
        $("seal").addEventListener("click", openIt);

        /* Counter */
        var start = CONFIG.startDate ? new Date(CONFIG.startDate) : null;
        if (!start || isNaN(start)) {
          $("counterBox").style.display = "none";
        } else {
          var tick = function () {
            var s = Math.max(
              0,
              Math.floor((Date.now() - start.getTime()) / 1000),
            );
            $("cd").textContent = Math.floor(s / 86400);
            $("ch").textContent = Math.floor((s % 86400) / 3600);
            $("cm").textContent = Math.floor((s % 3600) / 60);
            $("cs").textContent = s % 60;
          };
          tick();
          setInterval(tick, 1000);
        }

        /* Memories */
        var grid = $("memories");
        CONFIG.memories.forEach(function (m) {
          var b = document.createElement("button");
          b.type = "button";
          b.className = "polaroid" + (m.src ? "" : " empty");
          var media;
          if (m.src) {
            media = document.createElement("img");
            media.className = "ph";
            media.src = m.src;
            media.alt = m.caption || "Hamari yaad";
            media.loading = "lazy";
          } else {
            media = document.createElement("div");
            media.className = "ph";
            media.textContent = "\uD83D\uDCF7";
          }
          var cap = document.createElement("span");
          cap.className = "cap";
          cap.textContent = m.caption || "";
          b.appendChild(media);
          b.appendChild(cap);
          if (m.date) {
            var d = document.createElement("span");
            d.className = "dt";
            d.textContent = m.date;
            b.appendChild(d);
          }
          if (m.src) {
            b.addEventListener("click", function () {
              $("lbImg").src = m.src;
              $("lbImg").alt = m.caption || "";
              $("lbCap").textContent = m.caption || "";
              $("lightbox").classList.add("show");
            });
          } else {
            b.setAttribute("tabindex", "-1");
          }
          grid.appendChild(b);
        });
        function closeLb() {
          $("lightbox").classList.remove("show");
        }
        $("lbClose").addEventListener("click", closeLb);
        $("lightbox").addEventListener("click", function (e) {
          if (e.target === this) closeLb();
        });
        document.addEventListener("keydown", function (e) {
          if (e.key === "Escape") closeLb();
        });

        /* Hearts */
        function hearts(n) {
          var set = [
            "\u2764\uFE0F",
            "\uD83D\uDC96",
            "\uD83D\uDC97",
            "\uD83D\uDC95",
            "\uD83D\uDC9D",
          ];
          for (var i = 0; i < n; i++) {
            var h = document.createElement("span");
            h.className = "heart";
            h.textContent = set[i % set.length];
            h.style.left = Math.random() * 92 + "vw";
            h.style.fontSize = 18 + Math.random() * 26 + "px";
            h.style.setProperty("--d", 2.6 + Math.random() * 2 + "s");
            h.style.setProperty("--x", Math.random() * 80 - 40 + "px");
            h.style.setProperty("--rot", Math.random() * 60 - 30 + "deg");
            h.style.animationDelay = Math.random() * 0.8 + "s";
            document.body.appendChild(h);
            (function (el) {
              setTimeout(function () {
                el.remove();
              }, 6000);
            })(h);
          }
        }
        var msgs = [
          "Aur mujhe tumhari, tumse zyada.",
          "Bas thoda aur, phir hum saath honge.",
          "Main yahin hoon, hamesha.",
        ];
        var mi = 0;
        $("miss").addEventListener("click", function () {
          $("reply").textContent = msgs[mi++ % msgs.length] + " \u2764\uFE0F";
          hearts(reduce ? 6 : 28);
        });

        if (reduce) {
          var t = $("travel");
          if (t) {
            var a = t.querySelector("animateMotion");
            if (a) a.remove();
            t.setAttribute("x", "260");
            t.setAttribute("y", "50");
          }
        }
      })();
  